import React from 'react';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { Check, ShoppingBag, X } from 'lucide-react';
import { statusMeta } from '../data/mock';
import { useCourier } from '../lib/store';

export const cn = (...classes) => classes.filter(Boolean).join(' ');

export const Logo = ({ compact = false, light = false }) => (
  <Link to="/" className="group flex items-center gap-2.5">
    <span className="accent-bg relative flex h-10 w-10 items-center justify-center rounded-2xl shadow-glow transition-transform group-active:scale-95">
      <ShoppingBag size={20} className="text-white" strokeWidth={2.4} />
      <span className="absolute -right-1 -top-1 flex h-3.5 w-3.5 items-center justify-center rounded-full bg-lime-400 text-[8px] font-black text-brand-900 shadow">✓</span>
    </span>
    {!compact && (
      <span className="leading-none">
        <span className={`block font-display text-xl font-extrabold tracking-tight ${light ? 'text-white' : ''}`}>
          Max<span className={light ? 'text-lime-300' : 'text-gradient'}>SHOP</span>
        </span>
        <span className={`mt-1 block text-[9px] font-bold uppercase tracking-[0.22em] ${light ? 'text-white/60' : 'text-[var(--muted)]'}`}>courier</span>
      </span>
    )}
  </Link>
);

export const StatusBadge = ({ status }) => {
  const { t } = useTranslation();
  const meta = statusMeta[status] ?? statusMeta.new;
  return (
    <span className={cn('badge', meta.tone)}>
      <span className="h-1.5 w-1.5 rounded-full bg-current opacity-70" />
      {t(meta.labelKey)}
    </span>
  );
};

export const StatCard = ({ icon, label, value, hint, tone = 'brand' }) => {
  const tones = {
    brand: 'bg-brand-500/10 text-brand-600 dark:text-brand-400',
    amber: 'bg-amber-400/15 text-amber-600 dark:text-amber-400',
    sky: 'bg-sky-400/15 text-sky-600 dark:text-sky-400',
    violet: 'bg-violet-400/15 text-violet-600 dark:text-violet-400',
  };
  return (
    <div className="card card-lift p-3.5">
      <span className={cn('relative flex h-10 w-10 items-center justify-center rounded-2xl', tones[tone])}>{icon}</span>
      <p className="mt-2.5 font-display text-lg font-extrabold leading-none tracking-tight">{value}</p>
      <p className="mt-1 text-[10px] font-bold text-[var(--muted)]">{label}</p>
      {hint && <p className="mt-1 text-[9px] font-bold text-brand-600 dark:text-brand-400">{hint}</p>}
    </div>
  );
};

export const SectionHead = ({ title, right }) => (
  <div className="mb-2.5 flex items-center justify-between">
    <h2 className="font-display text-[15px] font-extrabold tracking-tight">{title}</h2>
    {right}
  </div>
);

export const Segmented = ({ options, value, onChange }) => (
  <div className="no-scrollbar flex gap-1.5 overflow-x-auto">
    {options.map((opt) => (
      <button
        key={opt.value}
        onClick={() => onChange(opt.value)}
        className={cn('chip shrink-0', value === opt.value && 'chip-active')}
      >
        {opt.label}
        {opt.count > 0 && (
          <span className={cn('rounded-full px-1.5 text-[9px]', value === opt.value ? 'bg-white/25' : 'bg-[var(--surface-2)]')}>{opt.count}</span>
        )}
      </button>
    ))}
  </div>
);

