export const Toaster = () => {
  const { toasts, dismissToast } = useCourier();
  return (
    <div className="pointer-events-none fixed inset-x-0 top-3 z-[100] flex flex-col items-center gap-2 px-4">
      {toasts.map((toast) => (
        <div key={toast.id} className={cn('glass-bar pointer-events-auto flex w-full max-w-sm items-center gap-2.5 rounded-2xl px-3.5 py-2.5 shadow-2xl animate-pop', toast.type === 'error' ? 'border-rose-400/40' : toast.type === 'info' ? 'border-sky-400/40' : 'border-brand-400/40')}>
          <span className={cn('flex h-7 w-7 shrink-0 items-center justify-center rounded-xl', toast.type === 'info' ? 'bg-sky-500/15 text-sky-600' : 'accent-bg text-white')}>
            {toast.type === 'info' ? 'i' : <Check size={13} strokeWidth={3.5} />}
          </span>
          <p className="flex-1 text-[11px] font-bold">{toast.message}</p>
          <button onClick={() => dismissToast(toast.id)} className="text-[var(--muted)] transition hover:text-rose-500"><X size={14} /></button>
        </div>
      ))}
    </div>
  );
};

export const EmptyState = ({ icon, title, description, action }) => (
  <div className="card flex flex-col items-center justify-center border-dashed px-5 py-12 text-center">
    <div className="relative">
      <span className="absolute inset-0 rounded-[1.25rem] bg-brand-500/20 blur-md" />
      <div className="relative flex h-16 w-16 items-center justify-center rounded-[1.25rem] bg-brand-500/10 text-brand-600 dark:text-brand-400">{icon}</div>
    </div>
    <h3 className="mt-4 font-display text-base font-extrabold">{title}</h3>
    {description && <p className="mt-1.5 max-w-xs text-xs text-[var(--muted)]">{description}</p>}
    {action && <div className="mt-4">{action}</div>}
  </div>
);
